function solve(s) {
    const chars = s.split('');
    const isVowel = (c) => 'aeiouAEIOU'.includes(c);
    let i = 0;
    let j = chars.length - 1;
    while (i < j) {
        if (!isVowel(chars[i])) i += 1;
        else if (!isVowel(chars[j])) j -= 1;
        else {
            [chars[i], chars[j]] = [chars[j], chars[i]];
            i += 1;
            j -= 1;
        }
    }
    return chars.join('');
}

