    const n = arr.length;
    let best = 0;
    for (let i = 1; i < n - 1; i++) {
        if (arr[i - 1] < arr[i] && arr[i] > arr[i + 1]) {
            let l = i - 1;
            while (l > 0 && arr[l - 1] < arr[l]) l -= 1;
            let r = i + 1;
            while (r < n - 1 && arr[r] > arr[r + 1]) r += 1;
            best = Math.max(best, r - l + 1);
        }
    }
    return best;
}
